CustomField.formula:
/*If phone field is blank, return blank */
IF(ISBLANK(Phone), "",

/*If the phone number starts with '+1' remove all of the non-number characters, if it does not start with "+1" add that to the beginning and remove all the other non-number characters.*/
IF(LEFT(Phone, 2) = "+1",
SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(
Phone, "(", ""), ")", ""), "-", ""), " ", ""), ".", ""),
"+1" & SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(
Phone, "(", ""), ")", ""), "-", ""), " ", ""), ".", "")
)
)
